package ai.eva.android.probe;
import android.content.*;import android.database.Cursor;import android.net.Uri;import android.provider.OpenableColumns;import java.io.*;import org.json.*;
/** Copies only user-selected documents; no broad storage permission. */
final class WorkspaceFiles {
 static File root(Context c)throws IOException{return new File(c.getFilesDir(),"alpine/root/eva-workspace").getCanonicalFile();}
 static File resolve(Context c,String relative)throws IOException{File root=root(c).getCanonicalFile(),f=new File(root,relative).getCanonicalFile();if(!f.toPath().startsWith(root.toPath()))throw new IOException("文件不在工作区内");return f;}
 static File project(Context c,String id)throws IOException{if(!id.isEmpty()&&!id.matches("[a-zA-Z0-9-]{1,64}"))throw new IOException("无效项目编号");File f=resolve(c,id.isEmpty()?"":"projects/"+id);if(!f.isDirectory()&&!f.mkdirs())throw new IOException("无法创建项目目录");return f;}
 static JSONObject importUri(Context c,Uri uri,String project)throws Exception{String name="附件";try(Cursor cursor=c.getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())name=cursor.getString(0);}if(name==null)name="附件";name=name.replaceAll("[\\\\/\\p{Cntrl}]","_");if(name.length()>120)name=name.substring(name.length()-120);File dir=new File(project(c,project),"attachments/"+java.util.UUID.randomUUID());if(!dir.mkdirs())throw new IOException("无法创建附件目录");File dest=new File(dir,name);long size=0;try(InputStream in=c.getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(dest)){if(in==null)throw new IOException("无法读取文件");byte[] buf=new byte[32768];int n;while((n=in.read(buf))!=-1){size+=n;if(size>32L*1024*1024)throw new IOException("单个附件不能超过 32 MB");out.write(buf,0,n);}}catch(Exception e){dest.delete();dir.delete();throw e;}String relative=root(c).toPath().relativize(dest.toPath()).toString().replace('\\','/');return new JSONObject().put("id",java.util.UUID.randomUUID().toString()).put("name",name).put("size",size).put("mime",c.getContentResolver().getType(uri)).put("path","/root/eva-workspace/"+relative);}
 static Intent picker(Context c,boolean photos){if(photos&&android.os.Build.VERSION.SDK_INT>=33){Intent photo=new Intent(android.provider.MediaStore.ACTION_PICK_IMAGES).setType("image/*").putExtra(android.provider.MediaStore.EXTRA_PICK_IMAGES_MAX,10);if(photo.resolveActivity(c.getPackageManager())!=null)return photo;}Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(photos?"image/*":"*/*");i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);return i;}
 static void export(Context c,File f,Uri uri)throws Exception{File source=resolve(c,root(c).toPath().relativize(f.getCanonicalFile().toPath()).toString());if(!source.isFile())throw new IOException("文件不存在");try(InputStream in=new FileInputStream(source);OutputStream out=c.getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("无法写入目标文件");byte[] buf=new byte[32768];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}}
}
